{"path": "server.js", "content": "import { createServer } from "node:http";
import { randomUUID } from "node:crypto";
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const DATA_FILE = join(__dirname, "books.json");
const PORT = process.env.PORT || 3000;

/** @typedef {{ id: string, title: string, author: string, status: "reading" | "finished", notes: string, addedAt: string }} Book */

const esc = (s) =>
  String(s ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");

const multi = (s) => esc(s).replaceAll("\n", "<br>");

async function loadBooks() {
  try {
    const raw = await readFile(DATA_FILE, "utf8");
    const data = JSON.parse(raw);
    return Array.isArray(data?.books) ? data.books : [];
  } catch (err) {
    if (err.code === "ENOENT") return [];
    throw err;
  }
}

async function saveBooks(books) {
  await mkdir(dirname(DATA_FILE), { recursive: true });
  await writeFile(DATA_FILE, JSON.stringify({ books }, null, 2) + "\n", "utf8");
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)} · Bookshelf</title>
<style>
  :root { --bg:#faf8f4; --card:#fff; --ink:#2b2b2b; --muted:#7a7a7a; --accent:#6b4a2b; --line:#e6e1d8; }
  * { box-sizing: border-box; }
  body { margin:0; background:var(--bg); color:var(--ink);
    font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
    line-height:1.5; }
  header { border-bottom:1px solid var(--line); background:var(--card); }
  header .wrap { max-width:720px; margin:0 auto; padding:18px 20px; display:flex; align-items:baseline; gap:10px; }
  header a.brand { font-size:1.3rem; font-weight:600; color:var(--ink); text-decoration:none; }
  header nav a { color:var(--muted); text-decoration:none; margin-left:16px; font-size:.95rem; }
  header nav a:hover { color:var(--accent); }
  main { max-width:720px; margin:0 auto; padding:28px 20px 60px; }
  h1 { font-size:1.5rem; margin:0 0 4px; }
  h2 { font-size:1.15rem; margin:32px 0 12px; color:var(--accent); }
  .muted { color:var(--muted); font-size:.9rem; }
  .cards { display:grid; gap:12px; }
  .card { background:var(--card); border:1px solid var(--line); border-radius:10px; padding:16px 18px; }
  .card a.title { font-size:1.1rem; font-weight:600; text-decoration:none; color:var(--ink); }
  .card a.title:hover { color:var(--accent); }
  .card .author { color:var(--muted); font-size:.92rem; margin-top:2px; }
  .card .actions { margin-top:12px; display:flex; gap:8px; flex-wrap:wrap; }
  .badge { font-size:.72rem; text-transform:uppercase; letter-spacing:.06em;
    padding:2px 8px; border-radius:999px; border:1px solid var(--line); color:var(--muted); }
  .badge.reading { color:#8a5a00; border-color:#e8c98a; background:#fff7e6; }
  .badge.finished { color:#2f6b3c; border-color:#bfe0c4; background:#eef8f0; }
  form.inline { display:inline; }
  input, textarea, select { font:inherit; }
  label { display:block; font-size:.9rem; color:var(--muted); margin:14px 0 4px; }
  input[type=text], textarea, select { width:100%; padding:9px 11px; border:1px solid var(--line);
    border-radius:8px; background:#fff; color:var(--ink); }
  textarea { min-height:120px; resize:vertical; }
  button { font:inherit; cursor:pointer; border-radius:8px; border:1px solid var(--line);
    background:#fff; color:var(--ink); padding:8px 14px; }
  button.primary { background:var(--accent); color:#fff; border-color:var(--accent); }
  button:hover { filter:brightness(1.03); }
  .row { display:flex; gap:10px; align-items:center; flex-wrap:wrap; }
  .share { font-family:ui-monospace,monospace; font-size:.82rem; color:var(--muted);
    background:#f3efe8; border:1px solid var(--line); border-radius:8px; padding:8px 10px;
    word-break:break-all; }
  .empty { color:var(--muted); font-style:italic; }
  a.back { text-decoration:none; color:var(--muted); font-size:.9rem; }
  a.back:hover { color:var(--accent); }
  .notes { margin-top:18px; }
  .notes p { margin:8px 0 0; white-space:normal; }
  .flash { background:#eef8f0; border:1px solid #bfe0c4; color:#2f6b3c;
    padding:10px 14px; border-radius:8px; margin-bottom:18px; }
</style>
</head>
<body>
<header><div class="wrap">
  <a class="brand" href="/">📚 Bookshelf</a>
  <nav><a href="/new">Add book</a></nav>
</div></header>
<main>
${body}
</main>
</body>
</html>`;
}

function bookCard(book, req) {
  const host = req.headers.host || `localhost:${PORT}`;
  const url = `http://${host}/book/${book.id}`;
  return `  <div class="card">
    <a class="title" href="/book/${esc(book.id)}">${esc(book.title)}</a>
    <div class="author">by ${esc(book.author)}</div>
    <div class="actions">
      <span class="badge ${book.status}">${book.status}</span>
      ${
        book.status === "reading"
          ? `<form class="inline" method="post" action="/book/${esc(book.id)}/finish"><button>Mark as finished</button></form>`
          : ""
      }
      <a href="/book/${esc(book.id)}">View &amp; share &rarr;</a>
    </div>
  </div>`;
}

function homePage(books, req) {
  const reading = books.filter((b) => b.status === "reading");
  const finished = books.filter((b) => b.status === "finished");
  const readingList = reading.length
    ? `<div class="cards">${reading.map((b) => bookCard(b, req)).join("")}</div>`
    : `<p class="empty">Nothing in progress yet. <a href="/new">Add a book</a> to get started.</p>`;
  const finishedList = finished.length
    ? `<div class="cards">${finished.map((b) => bookCard(b, req)).join("")}</div>`
    : `<p class="empty">No finished books yet.</p>`;
  return layout("My books", `
  <h1>My bookshelf</h1>
  <p class="muted">What you're reading and what you've finished.</p>
  <h2>Currently reading</h2>
  ${readingList}
  <h2>Finished</h2>
  ${finishedList}
  `);
}

function newFormPage(values = {}, error = "") {
  const v = values;
  const err = error ? `<div class="flash" style="background:#fdecec;border-color:#f3c4c4;color:#a02323">${esc(error)}</div>` : "";
  return layout("Add a book", `
  ${err}
  <h1>Add a book</h1>
  <form method="post" action="/new">
    <label for="title">Title</label>
    <input id="title" name="title" type="text" required value="${esc(v.title)}" autofocus>
    <label for="author">Author</label>
    <input id="author" name="author" type="text" required value="${esc(v.author)}">
    <label for="status">Status</label>
    <select id="status" name="status">
      <option value="reading" ${v.status !== "finished" ? "selected" : ""}>Currently reading</option>
      <option value="finished" ${v.status === "finished" ? "selected" : ""}>Finished</option>
    </select>
    <label for="notes">Notes <span class="muted">(optional)</span></label>
    <textarea id="notes" name="notes" placeholder="Thoughts, quotes, where you left off…">${esc(v.notes)}</textarea>
    <div style="margin-top:18px" class="row">
      <button class="primary" type="submit">Add book</button>
      <a class="back" href="/">Cancel</a>
    </div>
  </form>
  `);
}

function detailPage(book, req, flash = "") {
  const host = req.headers.host || `localhost:${PORT}`;
  const url = `http://${host}/book/${book.id}`;
  const finishBtn =
    book.status === "reading"
      ? `<form class="inline" method="post" action="/book/${esc(book.id)}/finish"><button class="primary">Mark as finished</button></form>`
      : "";
  const flashBox = flash ? `<div class="flash">${esc(flash)}</div>` : "";
  return layout(book.title, `
  ${flashBox}
  <a class="back" href="/">&larr; All books</a>
  <h1 style="margin-top:10px">${esc(book.title)}</h1>
  <div class="muted">by ${esc(book.author)}</div>
  <div class="row" style="margin-top:14px">
    <span class="badge ${book.status}">${book.status}</span>
    ${finishBtn}
  </div>
  <h2>Share</h2>
  <p class="muted">Send someone this link to show them this book:</p>
  <div class="share">${esc(url)}</div>
  <h2>Notes</h2>
  <form method="post" action="/book/${esc(book.id)}/notes">
    <textarea name="notes" placeholder="Write your notes…">${esc(book.notes)}</textarea>
    <div class="row" style="margin-top:10px">
      <button class="primary" type="submit">Save notes</button>
    </div>
  </form>
  `);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (c) => {
      data += c;
      if (data.length > 1e6) reject(new Error("body too large"));
    });
    req.on("end", () => resolve(Object.fromEntries(new URLSearchParams(data))));
    req.on("error", reject);
  });
}

function redirect(res, location) {
  res.writeHead(303, { location });
  res.end();
}

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url, `http://${req.headers.host || `localhost:${PORT}`}`);
    const path = url.pathname;
    const method = req.method;

    // Static: a tiny favicon so browsers stop 404-ing.
    if (path === "/favicon.ico") {
      res.writeHead(204);
      return res.end();
    }

    if (path === "/" && method === "GET") {
      const books = await loadBooks();
      res.writeHead(200, { "content-type": "text/html; charset=utf-8" });
      return res.end(homePage(books, req));
    }

    if (path === "/new" && method === "GET") {
      res.writeHead(200, { "content-type": "text/html; charset=utf-8" });
      return res.end(newFormPage());
    }

    if (path === "/new" && method === "POST") {
      const body = await readBody(req);
      const title = (body.title || "").trim();
      const author = (body.author || "").trim();
      if (!title || !author) {
        res.writeHead(200, { "content-type": "text/html; charset=utf-8" });
        return res.end(newFormPage(body, "Title and author are required."));
      }
      const books = await loadBooks();
      const book = {
        id: randomUUID().slice(0, 8),
        title,
        author,
        status: body.status === "finished" ? "finished" : "reading",
        notes: (body.notes || "").trim(),
        addedAt: new Date().toISOString(),
      };
      books.push(book);
      await saveBooks(books);
      return redirect(res, `/book/${book.id}`);
    }

    const detail = path.match(/^\/book\/([a-z0-9-]+)$/i);
    if (detail) {
      const id = detail[1];
      const books = await loadBooks();
      const book = books.find((b) => b.id === id);
      if (!book) {
        res.writeHead(404, { "content-type": "text/html; charset=utf-8" });
        return res.end(layout("Not found", `
          <h1>Book not found</h1>
          <p class="muted">There's no book with that link. It may have been removed.</p>
          <a class="back" href="/">&larr; Back to your bookshelf</a>`));
      }

      if (method === "GET") {
        res.writeHead(200, { "content-type": "text/html; charset=utf-8" });
        return res.end(detailPage(book, req));
      }

      if (path.endsWith("/finish") && method === "POST") {
        book.status = "finished";
        await saveBooks(books);
        return redirect(res, `/book/${id}`);
      }

      if (path.endsWith("/notes") && method === "POST") {
        const body = await readBody(req);
        book.notes = (body.notes || "").trim();
        await saveBooks(books);
        res.writeHead(200, { "content-type": "text/html; charset=utf-8" });
        return res.end(detailPage(book, req, "Notes saved."));
      }
    }

    res.writeHead(404, { "content-type": "text/html; charset=utf-8" });
    res.end(layout("Not found", `<h1>Not found</h1><a class="back" href="/">Home</a>`));
  } catch (err) {
    console.error(err);
    res.writeHead(500, { "content-type": "text/html; charset=utf-8" });
    res.end(layout("Error", `<h1>Something went wrong</h1><pre>${esc(err.message)}</pre>`));
  }
});

server.listen(PORT, () => {
  console.log(`Bookshelf running at http://localhost:${PORT}`);
});
"}

